Looking at this task, I need to:

1. Create a Python script that reads selected indicators, Eurostat sample data, and config
2. Join the data, filter for numeric values, remove duplicates
3. Output a normalized long-format CSV

Let me write the solution:

<solution_file path="src/t02_load_eurostat.py">
import csv
import json
import os


def detect_column(headers, patterns):
    """Detect a column name from headers matching any of the given patterns."""
    for h in headers:
        hl = h.lower().replace('_', '').replace('-', '').replace(' ', '')
        for pat in patterns:
            if pat in hl:
                return h
    return None


def load_selected_indicators(path):
    """Load indicator_id -> indicator_name mapping from selected indicators CSV."""
    indicators = {}
    with open(path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        headers = reader.fieldnames or []

        # Determine indicator_id column
        id_col = detect_column(headers, ['indicatorid', 'id', 'code', 'variable'])
        # Determine indicator_name column
        name_col = detect_column(headers, ['indicatorname', 'name', 'label', 'description'])

        # Fallback: if no specific match, use first/second columns
        if id_col is None:
            id_col = headers[0]
        if name_col is None and len(headers) > 1:
            name_col = headers[1]

        for row in reader:
            iid = (row.get(id_col) or '').strip()
            iname = (row.get(name_col) or '').strip()
            if iid:
                indicators[iid] = iname
    return indicators


def detect_data_columns(headers):
    """Map Eurostat sample CSV headers to canonical field names."""
    mapping = {}

    for h in headers:
        hl = h.lower().replace('_', '').replace('-', '').replace(' ', '')

        # City ID
        if 'city' in hl and 'id' in hl:
            mapping['city_id'] = h
        elif hl in ('cityid', 'city', 'geo', 'geoid', 'id'):
            if 'city_id' not in mapping and 'city_name' not in mapping:
                mapping['city_id'] = h

        # City Name
        if 'city' in hl and 'name' in hl:
            mapping['city_name'] = h
        elif hl in ('cityname', 'name', 'label', 'geoname', 'geoname'):
            if 'city_name' not in mapping:
                mapping['city_name'] = h

        # Year
        if 'year' in hl or 'time' in hl or 'period' in hl:
            if 'year' not in mapping:
                mapping['year'] = h

        # Indicator ID
        if 'indicator' in hl and ('id' in hl or 'code' in hl):
            mapping['indicator_id'] = h
        elif hl in ('indicator', 'code', 'variable', 'var'):
            if 'indicator_id' not in mapping:
                mapping['indicator_id'] = h

        # Value
        if 'value' in hl:
            if 'value' not in mapping:
                mapping['value'] = h

        # Unit
        if 'unit' in hl:
            if 'unit' not in mapping:
                mapping['unit'] = h

    # Second pass for remaining mappings with simpler heuristics
    if 'city_id' not in mapping:
        for h in headers:
            hl = h.lower()
            if hl in ('city_id', 'city', 'geo'):
                mapping['city_id'] = h
                break
    if 'city_name' not in mapping:
        for h in headers:
            hl = h.lower()
            if hl in ('city_name', 'name', 'label', 'city'):
                if h not in mapping.values():
                    mapping['city_name'] = h
                    break
    if 'year' not in mapping:
        for h in headers:
            hl = h.lower()
            if hl in ('year', 'time', 'period'):
                mapping['year'] = h
                break
    if 'indicator_id' not in mapping:
        for h in headers:
            hl = h.lower()
            if hl in ('indicator_id', 'indicator', 'code'):
                mapping['indicator_id'] = h
                break
    if 'value' not in mapping:
        for h in headers:
            hl = h.lower()
            if hl in ('value', 'val'):
                mapping['value'] = h
                break
    if 'unit' not in mapping:
        for h in headers:
            hl = h.lower()
            if hl in ('unit', 'unit_code'):
                mapping['unit'] = h
                break

    return mapping


def is_numeric(val):
    """Check if a string value represents a numeric value."""
    if val is None or str(val).strip() == '':
        return False
    try:
        float(str(val).strip())
        return True
    except (ValueError, TypeError):
        return False


def main():
    # Load selected indicators
    selected = load_selected_indicators('outputs/t01_selected_indicators.csv')

    # Load Eurostat sample data
    with open('inputs/eurostat/eurostat_city_values_sample.csv', 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        data_headers = reader.fieldnames or []
        rows = list(reader)

    # Map columns
    col_map = detect_data_columns(data_headers)

    # Process rows
    seen_keys = set()
    output_rows = []

    for row in rows:
        city_id = (row.get(col_map.get('city_id', ''), '') or '').strip()
        city_name = (row.get(col_map.get('city_name', ''), '') or '').strip()
        year = (row.get(col_map.get('year', ''), '') or '').strip()
        indicator_id = (row.get(col_map.get('indicator_id', ''), '') or '').strip()
        value = (row.get(col_map.get('value', ''), '') or '').strip()
        unit = (row.get(col_map.get('unit', ''), '') or '').strip()

        # Only include selected indicators
        if indicator_id not in selected:
            continue

        # Only include numeric values
        if not is_numeric(value):
            continue

        # Avoid duplicate city_id/year/indicator_id
        key = (city_id, year, indicator_id)
        if key in seen_keys:
            continue
        seen_keys.add(key)

        indicator_name = selected[indicator_id]

        output_rows.append({
            'city_id': city_id,
            'city_name': city_name,
            'year': year,
            'indicator_id': indicator_id,
            'indicator_name': indicator_name,
            'value': value,
            'unit': unit,
        })

    # Write output CSV (RFC 4180 compliant via csv.QUOTE_MINIMAL)
    os.makedirs('outputs', exist_ok=True)
    fieldnames = ['city_id', 'city_name', 'year', 'indicator_id', 'indicator_name', 'value', 'unit']
    with open('outputs/t02_eurostat_raw.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(
            f,
            fieldnames=fieldnames,
            quoting=csv.QUOTE_MINIMAL,
            quotechar='"',
            delimiter=',',
            lineterminator='\r\n',
        )
        writer.writeheader()
        for row in output_rows:
            writer.writerow(row)


if __name__ == '__main__':
    main()
